    /**
     * The heaviest expenses of `[from, to)`, largest first.
     */
    func topExpenses(vaultId: Uuid, from: UtcDateTime, to: UtcDateTime, person: String?, limit: UInt32) throws  -> [TopExpense]
    
    /**
