#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreHandle: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = CoreHandle

    public static func lift(_ handle: UInt64) throws -> CoreHandle {
        return CoreHandle(unsafeFromHandle: handle)
    }

    public static func lower(_ value: CoreHandle) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreHandle {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: CoreHandle, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCoreHandle_lift(_ handle: UInt64) throws -> CoreHandle {
    return try FfiConverterTypeCoreHandle.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCoreHandle_lower(_ value: CoreHandle) -> UInt64 {
    return FfiConverterTypeCoreHandle.lower(value)
}




