/**
 * Filter for [`Core::list_transactions`]. Defaults hide voided rows and
 * transfers.
 */
public struct TransactionFilter: Equatable, Hashable, Codable {
    /**
     * Inclusive.
     */
    public var from: UtcDateTime?
    /**
     * Exclusive.
     */
    public var to: UtcDateTime?
    /**
     * Allow-list; `None` = all kinds (minus transfers unless
     * `include_transfers`).
     */
    public var kinds: [TransactionKind]?
    public var includeVoided: Bool
    public var includeTransfers: Bool
    /**
     * Only transactions with a leg on this wallet.
     */
    public var walletId: Uuid?
    /**
     * Only transactions with a leg on this flow.
     */
    public var flowId: Uuid?
    /**
     * Case-insensitive substring on note or category name.
     */
    public var text: String?
    /**
     * Exact `created_by`: the PERSONA filter of the ledger
     * (`docs/v2/UI.md` §3). `None` = everybody.
     */
    public var author: String?
    /**
     * Oldest first, the reading order of the ledger. Cursors keep working:
     * they simply walk forward instead of backward.
     */
    public var ascending: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Inclusive.
         */from: UtcDateTime? = nil, 
        /**
         * Exclusive.
         */to: UtcDateTime? = nil, 
        /**
         * Allow-list; `None` = all kinds (minus transfers unless
         * `include_transfers`).
         */kinds: [TransactionKind]? = nil, includeVoided: Bool = false, includeTransfers: Bool = false, 
        /**
         * Only transactions with a leg on this wallet.
         */walletId: Uuid? = nil, 
        /**
         * Only transactions with a leg on this flow.
         */flowId: Uuid? = nil, 
        /**
         * Case-insensitive substring on note or category name.
         */text: String? = nil, 
        /**
         * Exact `created_by`: the PERSONA filter of the ledger
         * (`docs/v2/UI.md` §3). `None` = everybody.
         */author: String? = nil, 
        /**
         * Oldest first, the reading order of the ledger. Cursors keep working:
         * they simply walk forward instead of backward.
         */ascending: Bool = false) {
        self.from = from
        self.to = to
        self.kinds = kinds
        self.includeVoided = includeVoided
        self.includeTransfers = includeTransfers
        self.walletId = walletId
        self.flowId = flowId
        self.text = text
        self.author = author
        self.ascending = ascending
    }

    

    
}

