/**
 * A relative or absolute date token from a quick-add line.
 */

public enum DateSpec: Equatable, Hashable, Codable {
    
    case today
    case yesterday
    /**
     * `N` days before today, `N >= 1`.
     */
    case daysAgo(UInt32
    )
    /**
     * Day and month, year resolved against a reference date.
     */
    case dayMonth(day: UInt8, month: UInt8
    )
    case date(NaiveDate
    )





}

