    typealias SwiftType = DateSpec

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DateSpec {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .today
        
        case 2: return .yesterday
        
        case 3: return .daysAgo(try FfiConverterUInt32.read(from: &buf)
        )
        
        case 4: return .dayMonth(day: try FfiConverterUInt8.read(from: &buf), month: try FfiConverterUInt8.read(from: &buf)
        )
        
        case 5: return .date(try FfiConverterTypeNaiveDate.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DateSpec, into buf: inout [UInt8]) {
        switch value {
        
        
        case .today:
            writeInt(&buf, Int32(1))
        
        
        case .yesterday:
            writeInt(&buf, Int32(2))
        
        
        case let .daysAgo(v1):
            writeInt(&buf, Int32(3))
            FfiConverterUInt32.write(v1, into: &buf)
            
        
        case let .dayMonth(day,month):
            writeInt(&buf, Int32(4))
            FfiConverterUInt8.write(day, into: &buf)
            FfiConverterUInt8.write(month, into: &buf)
            
        
        case let .date(v1):
            writeInt(&buf, Int32(5))
            FfiConverterTypeNaiveDate.write(v1, into: &buf)
            
        }
    }
}


