/**
 * Error returned by every core operation.
 *
 * `code()` is stable and meant to reach the UI unchanged; the message is
 * for logs and developers.
 */
public 
enum DomainError: Swift.Error, Equatable, Hashable, Codable, Foundation.LocalizedError {

    
    
    case InsufficientFunds(message: String)
    
    case MaxBalanceReached(message: String)
    
    case NotFound(message: String)
    
    case AlreadyExists(message: String)
    
    case InvalidAmount(message: String)
    
    case InvalidName(message: String)
    
    case InvalidFlow(message: String)
    
    case CurrencyMismatch(message: String)
    
    case InvalidCommand(message: String)
    
    case InvalidCursor(message: String)
    
    case Storage(message: String)
    

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

